import React, { useState } from "react";
import FileUpload from "../../components/dashboard/FileUpload";
import StatsOverview from "../../components/dashboard/StatsOverview";
import DistributionAnalysis from "../../components/dashboard/DistributionAnalysis";
import CorrelationMatrix from "../../components/dashboard/CorrelationMatrix";
import ChartDisplay from "../../components/dashboard/ChartDisplay";
import DataPreview from "../../components/dashboard/DataPreview";

export default function Dashboard() {
  const [file, setFile] = useState(null);
  const [data, setData] = useState(null);
  const [statistics, setStatistics] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleFileUpload = async (uploadedFile) => {
    setFile(uploadedFile);
    setLoading(true);
    setError(null);

    try {
      const form = new FormData();
      form.append("file", uploadedFile);
      const uploadRes = await fetch("http://localhost:3000/upload", {
        method: "POST",
        body: form,
      });

      if (!uploadRes.ok) {
        const errorData = await uploadRes.json().catch(() => ({}));
        throw new Error(errorData.error || "Upload failed");
      }

      const { filename } = await uploadRes.json();

      const statsRes = await fetch(`http://localhost:3000/stats/${filename}`);
      if (!statsRes.ok) throw new Error("Failed to calculate statistics");
      const statsData = await statsRes.json();

      const dataRes = await fetch(`http://localhost:3000/uploads/${filename}`);
      if (!dataRes.ok) throw new Error("Failed to load data preview");
      const csvData = await dataRes.text();
      const [headers, ...rows] = csvData.trim().split("\n");
      const parsedData = rows.map((row) => {
        const values = row.split(",");
        return headers.split(",").reduce((obj, header, i) => {
          obj[header.trim()] = values[i]?.trim();
          return obj;
        }, {});
      });

      setData(parsedData);
      setStatistics(statsData);
    } catch (e) {
      setError(e.message);
      setFile(null);
    } finally {
      setLoading(false);
    }
  };

  const handleReset = () => {
    setFile(null);
    setData(null);
    setStatistics(null);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 py-6 sm:py-8">
        {!data ? (
          <FileUpload onFileUpload={handleFileUpload} loading={loading} error={error} />
        ) : (
          <div className="space-y-8">
            <StatsOverview data={data} fileName={file?.name} statistics={statistics?.columnStats} />
            <DistributionAnalysis data={data} statistics={statistics?.columnStats} />
            <CorrelationMatrix statistics={statistics?.correlations} />
            <ChartDisplay data={data} statistics={statistics?.columnStats} />
            <DataPreview data={data} />

            <div className="flex gap-3">
              <button
                onClick={() => {
                  const exportData = { fileName: file?.name, statistics, raw_data: data };
                  const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: "application/json" });
                  const url = URL.createObjectURL(blob);
                  const a = document.createElement("a");
                  a.href = url;
                  a.download = `statistical-analysis-${Date.now()}.json`;
                  a.click();
                  URL.revokeObjectURL(url);
                }}
                className="px-4 py-2 rounded-lg bg-indigo-600 text-white"
              >
                Export JSON
              </button>
              <button onClick={handleReset} className="px-4 py-2 rounded-lg bg-white/10 text-white border border-white/20">
                New Analysis
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

